function x(c,r,n=5){if(Array.isArray(r))return r;const e=c.filter(o=>typeof o=="number"&&isFinite(o)).sort((o,l)=>o-l);if(e.length===0)return[];const f=e[0],h=e[e.length-1];if(r==="equal"){const o=(h-f)/n,l=[];for(let t=1;t<n;t++)l.push(f+o*t);return l}if(r==="quantile"){const o=[],l=e.length;for(let t=1;t<n;t++){const i=(l-1)*(t/n),g=Math.floor(i),p=i-g;let y;e[g+1]!==void 0?y=e[g]+p*(e[g+1]-e[g]):y=e[g],o.push(y)}return o}return r==="jenks"?j(e,n):[]}function j(c,r){const n=c.length,e=Array.from({length:n+1},()=>new Array(r+1).fill(0)),f=Array.from({length:n+1},()=>new Array(r+1).fill(0));for(let t=1;t<=r;t++){e[1][t]=1,f[1][t]=0;for(let i=2;i<=n;i++)f[i][t]=1/0}let h=0;for(let t=2;t<=n;t++){let i=0,g=0,p=0;for(let y=1;y<=t;y++){const s=t-y+1,A=c[s-1];g+=A*A,i+=A,p++,h=g-i*i/p;const k=s-1;if(k!==0)for(let u=2;u<=r;u++)f[t][u]>=h+f[k][u-1]&&(e[t][u]=s,f[t][u]=h+f[k][u-1])}e[t][1]=1,f[t][1]=h}const o=new Array(r+1);o[r]=c[n-1],o[0]=c[0];let l=n;for(let t=r;t>=2;t--){const i=e[l][t]-2;o[t-1]=c[i],l=e[l][t]-1}return o.slice(1,r)}function w(c,r){for(let n=0;n<r.length;n++)if(c<=r[n])return n;return r.length}export{x as calculateBreaks,w as getClassIndex};
